-- 293: PDA audit tables move from request-time DDL to the migration contract.
-- Validate BOTH existing tables completely before any table is created or changed.
-- Only known signed/nullable/default/PK/index shapes and legacy/target utf8mb4 collations pass.
-- Preserve column definitions, comments, timestamps, quantities, IDs and all historical rows.
-- Partial DDL completion is accepted only when it is a known intermediate shape of this migration.

-- Preflight pda_error_logs; missing is allowed, unknown existing shape is not.
SET @pda293_error_present := (SELECT COUNT(*) FROM information_schema.TABLES t WHERE t.TABLE_SCHEMA=DATABASE() AND BINARY t.TABLE_NAME=BINARY 'pda_error_logs');
SET @pda293_error_table_ok := (SELECT COUNT(*)=1 FROM information_schema.TABLES t WHERE t.TABLE_SCHEMA=DATABASE() AND BINARY t.TABLE_NAME=BINARY 'pda_error_logs' AND t.TABLE_TYPE='BASE TABLE' AND t.ENGINE='InnoDB' AND t.TABLE_COLLATION IN ('utf8mb4_unicode_ci','utf8mb4_0900_ai_ci'));
SET @pda293_error_columns_ok := (SELECT COUNT(*)=7 AND COALESCE(SUM(
    (BINARY c.COLUMN_NAME=BINARY 'id' AND c.ORDINAL_POSITION=1 AND COALESCE(c.GENERATION_EXPRESSION,'')='' AND c.IS_NULLABLE='NO' AND c.DATA_TYPE='int' AND c.COLUMN_TYPE IN ('int','int(11)') AND c.NUMERIC_PRECISION=10 AND c.NUMERIC_SCALE=0 AND c.COLUMN_DEFAULT IS NULL AND c.EXTRA='auto_increment' AND c.CHARACTER_SET_NAME IS NULL AND c.COLLATION_NAME IS NULL)
    OR (BINARY c.COLUMN_NAME=BINARY 'task_id' AND c.ORDINAL_POSITION=2 AND COALESCE(c.GENERATION_EXPRESSION,'')='' AND c.IS_NULLABLE='YES' AND c.DATA_TYPE='int' AND c.COLUMN_TYPE IN ('int','int(11)') AND c.NUMERIC_PRECISION=10 AND c.NUMERIC_SCALE=0 AND c.COLUMN_DEFAULT IS NULL AND c.EXTRA='' AND c.CHARACTER_SET_NAME IS NULL AND c.COLLATION_NAME IS NULL)
    OR (BINARY c.COLUMN_NAME=BINARY 'barcode' AND c.ORDINAL_POSITION=3 AND COALESCE(c.GENERATION_EXPRESSION,'')='' AND c.IS_NULLABLE='YES' AND c.DATA_TYPE='varchar' AND c.COLUMN_TYPE='varchar(64)' AND c.CHARACTER_MAXIMUM_LENGTH=64 AND c.CHARACTER_SET_NAME='utf8mb4' AND c.COLLATION_NAME IN ('utf8mb4_unicode_ci','utf8mb4_0900_ai_ci') AND c.COLUMN_DEFAULT IS NULL AND c.EXTRA='')
    OR (BINARY c.COLUMN_NAME=BINARY 'reason' AND c.ORDINAL_POSITION=4 AND COALESCE(c.GENERATION_EXPRESSION,'')='' AND c.IS_NULLABLE='YES' AND c.DATA_TYPE='varchar' AND c.COLUMN_TYPE='varchar(255)' AND c.CHARACTER_MAXIMUM_LENGTH=255 AND c.CHARACTER_SET_NAME='utf8mb4' AND c.COLLATION_NAME IN ('utf8mb4_unicode_ci','utf8mb4_0900_ai_ci') AND c.COLUMN_DEFAULT IS NULL AND c.EXTRA='')
    OR (BINARY c.COLUMN_NAME=BINARY 'operator_id' AND c.ORDINAL_POSITION=5 AND COALESCE(c.GENERATION_EXPRESSION,'')='' AND c.IS_NULLABLE='YES' AND c.DATA_TYPE='int' AND c.COLUMN_TYPE IN ('int','int(11)') AND c.NUMERIC_PRECISION=10 AND c.NUMERIC_SCALE=0 AND c.COLUMN_DEFAULT IS NULL AND c.EXTRA='' AND c.CHARACTER_SET_NAME IS NULL AND c.COLLATION_NAME IS NULL)
    OR (BINARY c.COLUMN_NAME=BINARY 'operator_name' AND c.ORDINAL_POSITION=6 AND COALESCE(c.GENERATION_EXPRESSION,'')='' AND c.IS_NULLABLE='YES' AND c.DATA_TYPE='varchar' AND c.COLUMN_TYPE='varchar(64)' AND c.CHARACTER_MAXIMUM_LENGTH=64 AND c.CHARACTER_SET_NAME='utf8mb4' AND c.COLLATION_NAME IN ('utf8mb4_unicode_ci','utf8mb4_0900_ai_ci') AND c.COLUMN_DEFAULT IS NULL AND c.EXTRA='')
    OR (BINARY c.COLUMN_NAME=BINARY 'created_at' AND c.ORDINAL_POSITION=7 AND COALESCE(c.GENERATION_EXPRESSION,'')='' AND c.IS_NULLABLE='YES' AND c.DATA_TYPE='timestamp' AND c.COLUMN_TYPE='timestamp' AND c.DATETIME_PRECISION=0 AND LOWER(c.COLUMN_DEFAULT) IN ('current_timestamp','current_timestamp()') AND c.EXTRA IN ('','DEFAULT_GENERATED') AND c.CHARACTER_SET_NAME IS NULL AND c.COLLATION_NAME IS NULL)
  ),0)=7 FROM information_schema.COLUMNS c WHERE c.TABLE_SCHEMA=DATABASE() AND BINARY c.TABLE_NAME=BINARY 'pda_error_logs');
SET @pda293_error_indexes_ok := (SELECT COUNT(*) BETWEEN 1 AND 3
  AND COALESCE(SUM(CASE WHEN (BINARY s.INDEX_NAME=BINARY 'PRIMARY' AND BINARY s.COLUMN_NAME=BINARY 'id' AND s.NON_UNIQUE=0 AND s.INDEX_TYPE='BTREE' AND s.SEQ_IN_INDEX=1 AND s.SUB_PART IS NULL AND s.COLLATION='A' AND s.IS_VISIBLE='YES' AND s.EXPRESSION IS NULL)
    OR (BINARY s.INDEX_NAME=BINARY 'idx_pda_error_logs_created' AND BINARY s.COLUMN_NAME=BINARY 'created_at' AND s.NON_UNIQUE=1 AND s.INDEX_TYPE='BTREE' AND s.SEQ_IN_INDEX=1 AND s.SUB_PART IS NULL AND s.COLLATION='A' AND s.IS_VISIBLE='YES' AND s.EXPRESSION IS NULL)
    OR (BINARY s.INDEX_NAME=BINARY 'idx_pda_error_logs_task' AND BINARY s.COLUMN_NAME=BINARY 'task_id' AND s.NON_UNIQUE=1 AND s.INDEX_TYPE='BTREE' AND s.SEQ_IN_INDEX=1 AND s.SUB_PART IS NULL AND s.COLLATION='A' AND s.IS_VISIBLE='YES' AND s.EXPRESSION IS NULL) THEN 1 ELSE 0 END),0)=COUNT(*)
  AND SUM(BINARY s.INDEX_NAME=BINARY 'PRIMARY')=1
  AND SUM(BINARY s.INDEX_NAME=BINARY 'idx_pda_error_logs_created')<=1
  AND SUM(BINARY s.INDEX_NAME=BINARY 'idx_pda_error_logs_task')<=1
  FROM information_schema.STATISTICS s WHERE s.TABLE_SCHEMA=DATABASE() AND BINARY s.TABLE_NAME=BINARY 'pda_error_logs');
SET @pda293_error_constraints_ok := (SELECT COUNT(*)=1 AND COALESCE(SUM(BINARY tc.CONSTRAINT_NAME=BINARY 'PRIMARY' AND tc.CONSTRAINT_TYPE='PRIMARY KEY'),0)=1 FROM information_schema.TABLE_CONSTRAINTS tc WHERE tc.TABLE_SCHEMA=DATABASE() AND BINARY tc.TABLE_NAME=BINARY 'pda_error_logs');
SET @pda293_error_ok := @pda293_error_present=0 OR (@pda293_error_table_ok AND @pda293_error_columns_ok AND @pda293_error_indexes_ok AND @pda293_error_constraints_ok);

-- Preflight pda_undo_logs; missing is allowed, unknown existing shape is not.
SET @pda293_undo_present := (SELECT COUNT(*) FROM information_schema.TABLES t WHERE t.TABLE_SCHEMA=DATABASE() AND BINARY t.TABLE_NAME=BINARY 'pda_undo_logs');
